import subprocess, re
from datetime import time

def parse_time_arg(s):
    if ":" not in s:
        if s.isdigit():
            return None, "premature end of input"
        else:
            return None, "input contains invalid characters"
    parts = s.split(":")
    if len(parts) > 2:
        return None, "trailing input"
    if not parts[0] or not parts[1]:
        if not parts[0]:
            return None, "input contains invalid characters"
        else:
            return None, "premature end of input"
    m1 = re.match(r"^(\d+)(.*)$", parts[1])
    if not m1:
        return None, "input contains invalid characters"
    mn_str, rest = m1.groups()
    if rest:
        return None, "trailing input"
    if not parts[0].isdigit():
        return None, "input contains invalid characters"
    hr = int(parts[0])
    mn = int(mn_str)
    if hr < 0 or hr > 23 or mn < 0 or mn > 59:
        return None, "input is out of range"
    return time(hr, mn), None

invalid_times = [
    "10:30:00",
    "2026-07-31 10:30",
    "invalid",
    "25:00",
    "10:60",
    "10:",
    "10",
    ":30",
    "10:30abc"
]

for t in invalid_times:
    res = subprocess.run(["./executable", "-f", "/tmp/test.bartib", "start", "-p", "P", "-d", "D", "-t", t], capture_output=True, text=True)
    orig_msg = res.stdout.split("\n")[0]
    t_obj, reason = parse_time_arg(t)
    my_msg = f"Can not parse \"{t}\" as time. Argument for -t/--time is ignored ({reason})"
    if orig_msg == my_msg:
        print(f"MATCH: {t!r}")
    else:
        print(f"DIFF: {t!r}")
        print(" ORIG:", orig_msg)
        print(" MY:  ", my_msg)
'"}

